{/* Product Detail Modal matching the Products Page style */}
      {selectedProduct && (
        <div className="product-modal-overlay" style={{
          position: 'fixed', top: 0, left: 0, width: '100%', height: '100%',
          backgroundColor: 'rgba(0,0,0,0.6)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000
        }}>
          <div className="product-modal-content" style={{
            backgroundColor: '#fff', padding: '35px', borderRadius: '16px', maxWidth: '650px', width: '90%', maxHeight: '90vh', overflowY: 'auto', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)'
          }}>
            <button 
              onClick={() => setSelectedProduct(null)} 
              style={{ float: 'right', background: 'none', border: 'none', fontSize: '20px', cursor: 'pointer', fontWeight: 'bold', color: '#64748b' }}
            >
              ✕
            </button>
            
            {/* Category / Pill Badge */}
            {selectedProduct.category && (
              <span style={{ display: 'inline-block', backgroundColor: '#f1f5f9', color: '#334155', padding: '4px 10px', borderRadius: '20px', fontSize: '11px', fontWeight: '700', textTransform: 'uppercase', marginBottom: '10px' }}>
                {selectedProduct.category}
              </span>
            )}

            <h2 style={{ margin: '0 0 15px 0', fontSize: '24px', fontWeight: '800', color: '#0f172a' }}>
              {selectedProduct.name || selectedProduct.title}
            </h2>

            <div style={{ width: '100%', height: '280px', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: '#f8fafc', borderRadius: '12px', marginBottom: '20px', overflow: 'hidden' }}>
              <img src={activeModalImage} alt="Product" style={{ maxHeight: '100%', maxWidth: '100%', objectFit: 'contain' }} />
            </div>

            <div style={{ display: 'flex', alignItems: 'center', gap: '15px', marginBottom: '15px' }}>
              <span style={{ fontSize: '24px', fontWeight: '800', color: '#130352' }}>
                ${parsePrice(selectedProduct.price)}
              </span>
            </div>

            <p style={{ color: '#475569', fontSize: '15px', lineHeight: '1.5', marginBottom: '25px' }}>
              {selectedProduct.description || 'No description available for this item.'}
            </p>

            {/* Embedded MongoDB Review Component with Ratings */}
            <div style={{ borderTop: '1px solid #e2e8f0', paddingTop: '20px' }}>
              <ProductReviews productId={selectedProduct._id || selectedProduct.id} productTitle={selectedProduct.name || selectedProduct.title} />
            </div>
          </div>
        </div>
      )}
